<?php require_once 'config/functions.php';if(!empty($_SESSION['user_id']))redirect('dashboard.php');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'', $u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['name']=$u['name'];redirect('dashboard.php');}$err='Email or password is incorrect.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title>Login | MindSpace</title></head><body class="auth"><div class="auth-card"><div class="brand">☁ MindSpace</div><h2>Welcome back 🌷</h2><p class="muted">A little time for yourself, every day.</p><?php show_flash();if(!empty($err))echo '<div class="flash">'.h($err).'</div>';?><form class="form" method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="field"><label>Email address</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button>Login</button></form><p class="muted">New here? <a href="register.php">Create an account</a></p></div></body></html>
